import json,pathlib,hashlib
root=pathlib.Path(__file__).resolve().parents[1]
def write(name,obj):
 p=root/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
def obj(props,required=None):return {'type':'object','additionalProperties':False,'properties':props,'required':list(props) if required is None else required}
def text(pattern=None):return {'type':'string',**({'pattern':pattern} if pattern else {})}
def nullable(schema):return {'anyOf':[schema,{'type':'null'}]}
def enum(*vals):return {'enum':list(vals)}
digest=text('^[0-9a-f]{64}$');counter=text('^(0|[1-9][0-9]*)$');stamp=text(r'^\d{4}-\d{2}-\d{2}T.*Z$');uuid={'type':'string','format':'uuid'}
