receipt['allOf']=[{'if':{'properties':{'outcome':{'const':'REJECTED'}}},'then':{'properties':{'signature':{'type':'null'},'submission':{'properties':{'state':{'const':'NOT_SUBMITTED'},'broadcast':{'const':False},'submittedByDeproof':{'const':False}}}}}},{'if':{'properties':{'outcome':{'const':'OBSERVED'}}},'then':{'properties':{'submission':{'properties':{'state':{'const':'NOT_SUBMITTED'},'broadcast':{'const':False},'submittedByDeproof':{'const':False}}}}}}]
for name,s in [('evidence-v2',manifest),('receipt-v2',receipt),('evidence-envelope-v2',obj({'domain':{'const':'deproof-evidence-sig-v2'},'manifestDigest':digest,'manifestSchema':{'const':'deproof-evidence-v2'},'algorithm':{'const':'SHA256withECDSA'}}))]:write('contracts/'+name+'.schema.json',{'$schema':'https://json-schema.org/draft/2020-12/schema',**s})
